import pytest
from PIL import Image
from mean_threshold import mean_threshold

class Test_MeanThresholdMeanThreshold:

    @pytest.mark.valid
    def test_uniform_pixel_values(self):
        # Arrange
        image = Image.new('L', (100, 100), 128)
        # Act
        result = mean_threshold(image)
        # Assert
        pixels = result.load()
        for i in range(100):
            for j in range(100):
                assert pixels[i, j] == 255

    @pytest.mark.valid
    def test_alternating_pixel_values(self):
        # Arrange
        image = Image.new('L', (10, 10))
        pixels = image.load()
        for i in range(10):
            for j in range(10):
                pixels[i, j] = 0 if (i + j) % 2 == 0 else 255
        # Act
        result = mean_threshold(image)
        # Assert
        pixels = result.load()
        for i in range(10):
            for j in range(10):
                assert pixels[i, j] == 0

    @pytest.mark.valid
    def test_random_pixel_values(self):
        # Arrange
        image = Image.new('L', (50, 50))
        pixels = image.load()
        for i in range(50):
            for j in range(50):
                pixels[i, j] = i * j % 256
        # Act
        result = mean_threshold(image)
        # Assert
        pixels = result.load()
        mean = sum(image.getdata()) // (50 * 50)
        for i in range(50):
            for j in range(50):
                assert pixels[i, j] == (255 if pixels[i, j] > mean else 0)

